// Simple Neon Escape game
// Canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = (canvas.width = canvas.clientWidth || 400);
  const h = (canvas.height = canvas.clientHeight || 600);

  const ship = { x: w / 2, y: h - 40, w: 30, h: 30, vx: 0, speed: 4 };
  const asteroids = [];
  let lastSpawn = 0;
  let startTime = performance.now();
  let gameOver = false;

  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  function spawnAsteroid() {
    const size = Math.random() * 30 + 20;
    asteroids.push({ x: Math.random() * (w - size), y: -size, w: size, h: size, vy: Math.random() * 2 + 2 });
  }

  function update(dt) {
    if (gameOver) return;
    // ship movement
    ship.vx = 0;
    if (keys['ArrowLeft'] || keys['a']) ship.vx = -ship.speed;
    if (keys['ArrowRight'] || keys['d']) ship.vx = ship.speed;
    ship.x = Math.max(0, Math.min(w - ship.w, ship.x + ship.vx));

    // spawn asteroids every ~1s
    if (performance.now() - lastSpawn > 1000) {
      spawnAsteroid();
      lastSpawn = performance.now();
    }

    // update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.vy;
      if (a.y > h) asteroids.splice(i, 1);
      // collision
      if (
        ship.x < a.x + a.w &&
        ship.x + ship.w > a.x &&
        ship.y < a.y + a.h &&
        ship.y + ship.h > a.y
      ) {
        gameOver = true;
      }
    }
  }

  function draw() {
    // clear
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, w, h);
    // neon style
    ctx.strokeStyle = '#0ff';
    ctx.lineWidth = 2;
    // ship (triangle)
    ctx.beginPath();
    ctx.moveTo(ship.x + ship.w / 2, ship.y);
    ctx.lineTo(ship.x, ship.y + ship.h);
    ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
    ctx.closePath();
    ctx.stroke();
    // asteroids (circles)
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x + a.w / 2, a.y + a.h / 2, a.w / 2, 0, Math.PI * 2);
      ctx.stroke();
    });
    // score
    ctx.fillStyle = '#0ff';
    ctx.font = '16px monospace';
    const score = Math.floor((performance.now() - startTime) / 1000);
    ctx.fillText('Score: ' + score, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'red';
      ctx.font = '24px monospace';
      ctx.fillText('Game Over', w / 2 - 60, h / 2);
    }
  }

  let last = performance.now();
  function loop() {
    const now = performance.now();
    const dt = now - last;
    last = now;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
